import importlib.util, subprocess
spec = importlib.util.spec_from_file_location("doclinks", "scripts/check-doc-links.py")
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)
run = subprocess.run
files = sorted(set(run(["git", "ls-files", "--cached", "--others", "--exclude-standard", "--", "*.md"], check=True, capture_output=True, text=True).stdout.splitlines()))
def including_new(args, **kwargs):
    if args == ["git", "ls-files", "*.md"]:
        return subprocess.CompletedProcess(args, 0, "\n".join(files), "")
    return run(args, **kwargs)
m.subprocess.run = including_new
raise SystemExit(m.main())
